using UnityEngine;using TMPro;using LWS.TruckSports;
namespace LWS.TruckKeepaway {
// One projected UI set per camera. World text never rotates toward competing cameras or enters a cab.
[DefaultExecutionOrder(220)]public sealed class KeepawayNameplates:MonoBehaviour {
 public KeepawayMatch match;public RectTransform[] panels,plates;public TMP_Text[] captions;public readonly Rect[] VisibleRects=new Rect[16];public readonly bool[] Visible=new bool[16];public readonly int[] Count=new int[4];public float maxDistance=75;readonly RaycastHit[] hits=new RaycastHit[32];readonly int[] order=new int[4];readonly float[] distances=new float[4];float refreshAt;
 void LateUpdate(){bool refresh=Time.unscaledTime>=refreshAt;if(refresh)refreshAt=Time.unscaledTime+.1f;for(int v=0;v<4;v++){Count[v]=0;bool active=match.Running&&match.menus.Screen==SportsEventScreen.Play&&v<match.cameras.Length&&match.cameras[v].enabled;panels[v].gameObject.SetActive(active);for(int i=0;i<4;i++){Visible[v*4+i]=false;}if(!active){for(int i=0;i<4;i++)plates[v*4+i].gameObject.SetActive(false);continue;}var camera=match.cameras[v];var viewport=camera.rect;panels[v].anchorMin=viewport.min;panels[v].anchorMax=viewport.max;panels[v].offsetMin=panels[v].offsetMax=Vector2.zero;var canvas=panels[v].parent.GetComponent<RectTransform>();float width=canvas.rect.width*viewport.width,height=canvas.rect.height*viewport.height;float upper=match.cabVariant&&match.HumanViews>0?.77f:.88f;for(int i=0;i<4;i++){order[i]=i;distances[i]=i<match.setup.count?Vector3.SqrMagnitude(match.trucks[i].body.position-camera.transform.position):float.PositiveInfinity;}for(int i=1;i<4;i++){int index=order[i],k=i-1;while(k>=0&&distances[order[k]]>distances[index]){order[k+1]=order[k];k--;}order[k+1]=index;}
 for(int rank=0;rank<match.setup.count;rank++){int i=order[rank],id=v*4+i;if(!match.alive[i]||match.cabVariant&&match.HumanViews>0&&match.CabSlot(v)==i)continue;var world=match.trucks[i].body.position+Vector3.up*2.65f;float distance=Vector3.Distance(camera.transform.position,world);if(distance<2.5f||distance>maxDistance)continue;var projected=camera.WorldToViewportPoint(world);if(projected.z<=camera.nearClipPlane||projected.x<.015f||projected.x>.985f||projected.y<.08f||projected.y>upper||Occluded(camera,world,i))continue;float plateWidth=Mathf.Min(240,width*.44f),plateHeight=30;var pos=new Vector2(Mathf.Clamp(projected.x*width,plateWidth*.5f+7,width-plateWidth*.5f-7),projected.y*height);Rect rect=default;bool clear=false;for(int attempt=0;attempt<4;attempt++){rect=new Rect(pos.x-plateWidth*.5f,pos.y-plateHeight*.5f,plateWidth,plateHeight);clear=rect.yMax<height*upper;for(int j=0;j<4&&clear;j++)if(Visible[v*4+j]&&rect.Overlaps(VisibleRects[v*4+j]))clear=false;if(clear)break;pos.y+=plateHeight+3;}if(!clear)continue;var plate=plates[id];plate.sizeDelta=new Vector2(plateWidth,plateHeight);plate.anchoredPosition=pos;plate.gameObject.SetActive(true);Visible[id]=true;VisibleRects[id]=rect;Count[v]++;captions[id].rectTransform.sizeDelta=plate.sizeDelta-new Vector2(10,2);if(refresh){string name=match.setup.players[i].name;if(name.Length>24)name=name.Substring(0,23)+"…";captions[id].text=name+(match.Carrier==i?" ●":"");captions[id].color=match.setup.players[i].color;}}for(int i=0;i<4;i++)if(!Visible[v*4+i])plates[v*4+i].gameObject.SetActive(false);}}
 bool Occluded(Camera camera,Vector3 world,int slot){var delta=world-camera.transform.position;float length=delta.magnitude;int count=Physics.RaycastNonAlloc(camera.transform.position,delta/length,hits,Mathf.Max(0,length-.3f),~(15<<26),QueryTriggerInteraction.Ignore);if(count==hits.Length)return true;for(int i=0;i<count;i++){var hit=hits[i];if(hit.rigidbody==match.trucks[slot].body||hit.collider==match.ballShape)continue;return true;}return false;}
}
}
